--
-- Parser for the hoogle files generated by haddock.
--
-- A file made by concatenating several hoogle files is parsed as one API:
-- @\@package@ and @\@version@ lines are collected and each @module@ line
-- starts a new module. A module that appears again replaces the earlier one.

module PackDiff.HoogleFileParser
    ( hoogleFold
    , parseHoogleLines
    , fileLines
    , readHoogleFile
    ) where

import Data.Char (isSpace, isUpper)
import Data.Function ((&))
import Data.List (isInfixOf, isPrefixOf, isSuffixOf, stripPrefix)
import Data.Maybe (isNothing)
import Streamly.Data.Fold (Fold)
import Streamly.Data.Stream (Stream)
import Streamly.FileSystem.Path (Path)

import qualified Data.Map.Strict as Map
import qualified Streamly.Data.Fold as Fold
import qualified Streamly.Data.Stream as Stream
import qualified Streamly.FileSystem.FileIO as File
import qualified Streamly.FileSystem.Path as Path
import qualified Streamly.Unicode.Stream as Unicode

import PackDiff.API
import PackDiff.Error (obtainError)

--------------------------------------------------------------------------------
-- Line classification helpers
--------------------------------------------------------------------------------

strip :: String -> String
strip = dropWhileEnd' . dropWhile isSpace

    where

    dropWhileEnd' = reverse . dropWhile isSpace . reverse

isDeprecatedDoc :: [String] -> Bool
isDeprecatedDoc = any ("<i>Deprecated:" `isInfixOf`)

-- | The name declared by a line that starts with a keyword, e.g. @data@. A
-- @family@ keyword after it is skipped.
nameAfterKeyword :: String -> String
nameAfterKeyword line =
    case words line of
        (_ : "family" : n : _) -> n
        (_ : n : _) -> n
        _ -> line

-- | The class name in a class declaration head, e.g. @MonadAsync@ in
-- @class Monad m => MonadAsync m@.
className :: String -> String
className line =
    let hd = takeWhileNotWhere (drop (length "class ") line)
     in case words (afterLastArrow hd) of
            (n : _) -> n
            [] -> hd

    where

    takeWhileNotWhere s =
        case breakOnStr " where" s of
            (a, _) -> a
    afterLastArrow s =
        case breakOnStr "=>" s of
            (_, Just rest) -> afterLastArrow rest
            (a, Nothing) -> a

-- | Split at the first occurrence of a separator, dropping the separator.
breakOnStr :: String -> String -> (String, Maybe String)
breakOnStr sep = go []

    where

    go acc s@(c : cs) =
        case stripPrefix sep s of
            Just rest -> (reverse acc, Just rest)
            Nothing -> go (c : acc) cs
    go acc [] = (reverse acc, Nothing)

-- | The type after @::@ in a signature, without a leading @forall ... .@.
signatureType :: String -> Maybe String
signatureType line =
    case breakOnStr " :: " line of
        (_, Just ty) -> Just (dropForall ty)
        (_, Nothing) -> Nothing

    where

    dropForall ty
        | "forall " `isPrefixOf` ty =
            case breakOnStr ". " ty of
                (_, Just rest) -> rest
                (_, Nothing) -> ty
        | otherwise = ty

-- | Whether a line is a constructor or a field of a data type.
isConstructorLine :: String -> Bool
isConstructorLine line =
    case line of
        (c : _) | isUpper c -> True
        ('[' : _) -> True
        ('(' : ':' : _) -> True
        _ -> False

-- | Haddock prints the methods of a class just after the class declaration,
-- with the class constraint first in the signature, e.g. @mapEmpty :: IsMap f
-- => f a@ after @class IsMap f@.
--
-- XXX The hoogle file does not mark class methods. A top level function that
-- directly follows a class and has the same leading constraint is taken to be
-- a method. Haddock interface files (@--show-interface@) would tell exactly.
isMethodOf :: String -> String -> Bool
isMethodOf cls line =
    case signatureType line of
        Just ty ->
            "=>" `isInfixOf` ty
                && ((cls ++ " ") `isPrefixOf` ty
                    || ("(" ++ cls ++ " ") `isPrefixOf` ty)
        Nothing -> False

--------------------------------------------------------------------------------
-- Parser state
--------------------------------------------------------------------------------

-- | A declaration that can still take children from the following lines.
data Open
    = OpenNone
    | OpenData !Decl
    | OpenClass !String !Bool !Decl
      -- ^ Class name, whether inside a multi line @where { ... }@, the class.

data St = St
    { stDoc :: ![String] -- reversed
    , stPackages :: ![String] -- reversed
    , stVersions :: ![String] -- reversed
    , stAPI :: !API
    , stModule :: !(Maybe (ModuleName, Module))
    , stOpen :: !Open
    , stLineNo :: !Int
    , stError :: !(Maybe String)
    }

initial :: St
initial =
    St
        { stDoc = []
        , stPackages = []
        , stVersions = []
        , stAPI = Map.empty
        , stModule = Nothing
        , stOpen = OpenNone
        , stLineNo = 0
        , stError = Nothing
        }

takeDoc :: St -> ([String], St)
takeDoc st = (reverse (stDoc st), st { stDoc = [] })

reverseChildren :: Decl -> Decl
reverseChildren d = d { declChildren = reverse (declChildren d) }

-- | Add the open declaration, if any, to the current module.
closeDecl :: St -> St
closeDecl st =
    case stOpen st of
        OpenNone -> st
        OpenData d -> insertDecl (reverseChildren d) st { stOpen = OpenNone }
        OpenClass _ _ d ->
            insertDecl (reverseChildren d) st { stOpen = OpenNone }

insertDecl :: Decl -> St -> St
insertDecl d st =
    case stModule st of
        Just (name, m) ->
            let m1 = m { moduleDecls = Map.insert (declKey d) d (moduleDecls m) }
             in st { stModule = Just (name, m1) }
        Nothing -> st

-- | Add the current module, if any, to the API.
closeModule :: St -> St
closeModule st0 =
    let st = closeDecl st0
     in case stModule st of
            Just (name, m) ->
                st { stAPI = Map.insert name m (stAPI st), stModule = Nothing }
            Nothing -> st

--------------------------------------------------------------------------------
-- Declarations
--------------------------------------------------------------------------------

mkDecl :: DeclKind -> String -> String -> [String] -> Decl
mkDecl kind name text doc =
    Decl
        { declKind = kind
        , declName = name
        , declText = text
        , declDoc = doc
        , declDeprecated = isDeprecatedDoc doc
        , declChildren = []
        }

mkChild :: String -> [String] -> Child
mkChild line doc =
    Child
        { childName = takeWhile (not . isSpace) line
        , childText = line
        , childDeprecated = isDeprecatedDoc doc
        }

addChild :: String -> St -> St
addChild line st0 =
    let (doc, st) = takeDoc st0
        add d = d { declChildren = mkChild line doc : declChildren d }
     in case stOpen st of
            OpenData d -> st { stOpen = OpenData (add d) }
            OpenClass c b d -> st { stOpen = OpenClass c b (add d) }
            OpenNone -> st

-- | A top level declaration line.
topLevel :: String -> St -> St
topLevel line st1 =
    let st0 = closeDecl st1
        (doc, st) = takeDoc st0
        insert kind name = insertDecl (mkDecl kind name line doc) st
        open kind name =
            st { stOpen = OpenData (mkDecl kind name line doc) }
     in case words line of
            ("data" : _) -> open KData (nameAfterKeyword line)
            ("newtype" : _) -> open KData (nameAfterKeyword line)
            ("type" : _) -> insert KTypeSyn (nameAfterKeyword line)
            ("class" : _) ->
                let multiline = "{" `isSuffixOf` line
                    cls = className line
                 in st { stOpen = OpenClass cls multiline (mkDecl KClass cls line doc) }
            ("instance" : _) ->
                insert KInstance (drop (length "instance ") line)
            ("pattern" : _) -> insert KPattern (nameAfterKeyword line)
            (fx : _ : ops)
                | fx `elem` ["infix", "infixl", "infixr"] ->
                    insert KFixity (unwords ops)
            _ -> insert KFunction (takeWhile (not . isSpace) line)

-- | A continuation line of a multi line class declaration, e.g. an associated
-- type. It is appended to the class declaration so that the declaration
-- stays on one line.
classContinuation :: String -> St -> St
classContinuation line st =
    case stOpen st of
        OpenClass c _ d ->
            let s = strip line
                d1 = d { declText = declText d ++ " " ++ s }
             in st { stOpen = OpenClass c (not ("}" `isPrefixOf` s)) d1 }
        _ -> st

--------------------------------------------------------------------------------
-- Line step
--------------------------------------------------------------------------------

stepLine :: St -> String -> St
stepLine st0 line0 =
    let st = st0 { stLineNo = stLineNo st0 + 1 }
        line = stripCR line0
     in case stError st of
            Just _ -> st
            Nothing -> go st line

    where

    stripCR s =
        case reverse s of
            ('\r' : rest) -> reverse rest
            _ -> s

    go st line
        | OpenClass _ True _ <- stOpen st = classContinuation line st
        | Just pkg <- stripPrefix "@package " line =
            (closeDecl st) { stPackages = strip pkg : stPackages st, stDoc = [] }
        | Just ver <- stripPrefix "@version " line =
            (closeDecl st) { stVersions = strip ver : stVersions st, stDoc = [] }
        | "@" `isPrefixOf` line = st { stDoc = [] }
        | "--" `isPrefixOf` line = st { stDoc = line : stDoc st }
        | all isSpace line = st
        | Just name <- stripPrefix "module " line =
            let (doc, st1) = takeDoc (closeModule st)
                m = Module
                        { moduleDoc = doc
                        , moduleDeprecated = isDeprecatedDoc doc
                        , moduleDecls = Map.empty
                        }
             in st1 { stModule = Just (strip name, m) }
        | isNothing (stModule st) =
            st { stError = Just $
                    "line " ++ show (stLineNo st)
                        ++ ": declaration outside a module: " ++ line }
        | otherwise =
            case stOpen st of
                OpenData _ | isConstructorLine line -> addChild line st
                OpenClass cls _ _ | isMethodOf cls line -> addChild line st
                _ -> topLevel line st

extract :: St -> Either String Hoogle
extract st0 =
    case stError st0 of
        Just err -> Left err
        Nothing ->
            let st = closeModule st0
             in Right Hoogle
                    { hooglePackages = reverse (stPackages st)
                    , hoogleVersions = reverse (stVersions st)
                    , hoogleAPI = stAPI st
                    }

--------------------------------------------------------------------------------
-- Interface
--------------------------------------------------------------------------------

-- | Parse the lines of a hoogle file.
hoogleFold :: Monad m => Fold m String (Either String Hoogle)
hoogleFold = fmap extract (Fold.foldl' stepLine initial)

parseHoogleLines :: [String] -> Either String Hoogle
parseHoogleLines = extract . foldl stepLine initial

-- | The lines of a UTF-8 encoded text file.
fileLines :: Path -> Stream IO String
fileLines path =
    File.read path
        & Unicode.decodeUtf8
        & Stream.foldMany (Fold.takeEndBy_ (== '\n') Fold.toList)

-- | Read and parse a hoogle file. A parse error is thrown as an
-- 'PackDiff.Error.ObtainError'.
readHoogleFile :: Path -> IO Hoogle
readHoogleFile path = do
    r <- fileLines path & Stream.fold hoogleFold
    either
        (\e -> obtainError $ Path.toString path ++ ": " ++ e)
        pure
        r

